// ⚑ REVIEW (slovná hračka / pointa oslabená) — Matej over: 01-08, 01-11, 01-21, 01-29, 02-10, 03-07, 03-13, 03-19, 03-30, 04-05, 05-15, 05-26, 07-09, 07-11, 08-18, 08-20, 08-29, 10-27, 11-07, 11-08, 11-15

export const DAILY_QUOTES_SK: Record<string, string> = {
  "01-01": "Nové šteniatko je jar srdca.",
  "01-02": "Jediný naozaj nezištný priateľ, akého môže mať človek v tomto sebeckom svete, jediný, ktorý ho nikdy neopustí a nikdy sa neukáže nevďačným ani zradným, je jeho pes.",
  "01-03": "Správne vychovaný, môže byť človek najlepším priateľom psa — ten mu rozloží deku a prinesie večeru, keď sa unavený vráti domov.",
  "01-04": "Čím lepšie spoznávam ľudí, tým viac milujem psov.",
  "01-05": "Pre svojho psa je každý človek Napoleon — odtiaľ tá neprestajná obľuba psov.",
  "01-06": "Pes stojí pri človeku v hojnosti aj v chudobe, v zdraví aj v chorobe. Bude spať na studenej zemi, kde fúka zimný vietor a sneh hnaný do tváre, len aby mohol byť blízko svojho pána.",
  "01-07": "Keď raz budete mať skvelého psa, život bez neho bude životom ochudobneným.",
  "01-08": "Okrem psa je kniha najlepším priateľom človeka. V psovi je na čítanie príliš tma.",
  "01-09": "Psi ma nikdy nehryzú. Iba ľudia.",
  "01-10": "Šťastie je teplé šteniatko.",
  "01-11": "Dvere sú niečo, na čoho nesprávnej strane sa pes nachádza dookola.",
  "01-12": "Mačky sú múdrejšie ako psi. Nedostanete osem mačiek, aby ťahali sane v snehu.",
  "01-13": "Také krátke životy majú naši domáci miláčikovia na prežitie s nami — a väčšinu z toho strávia čakaním, kedy sa každý deň vrátime domov.",
  "01-14": "Správne vycvičený môže byť človek najlepším priateľom psa.",
  "01-15": "Videl som v psích očiach pohľad — rýchlo miznúci pohľad udiveného opovrhnutia — a som presvedčený, že psi v zásade považujú ľudí za bláznov.",
  "01-16": "Pes naučí chlapca vernosti, vytrvalosti a otočiť sa trikrát pred tým, ako si ľahne.",
  "01-17": "Psi sú naším spojením s rajom. Nepoznajú zlo ani žiarlivosť ani nespokojnosť. Sedieť s psom na svahu kopca v nádherné popoludnie znamená byť späť v raji, kde nerobenie nič nebolo nudné — bolo to pokoj.",
  "01-18": "Psi žijú príliš krátko. To je vlastne ich jediná chyba.",
  "01-19": "Ak mám nejaké presvedčenie o nesmrteľnosti, je to presvedčenie, že niektorí psi, ktorých som poznal, sa dostanú do neba — a veľmi, veľmi málo ľudí.",
  "01-20": "Kým človek nemiloval zviera, časť jeho duše ostáva nevzbudená.",
  "01-21": "Pes — akési doplnkové alebo pomocné božstvo, stvorené na zachytenie pretečeného a prebytočného uctievania tohto sveta.",
  "01-22": "Naši dokonalí spoločníci nikdy nemajú menej ako štyri nohy.",
  "01-23": "Moja módna filozofia znie: ak nie ste pokrytí psími chlpmi, váš život je prázdny.",
  "01-24": "Psi milujú svojich priateľov a hryzú svojich nepriateľov — celkom na rozdiel od ľudí, ktorí nie sú schopní čistej lásky a vždy musia lásku miešať s nenávisťou.",
  "01-25": "V smútku nad stratou psa stojí malý chlapec po prvý raz na špičkách a nazerá do trpkého zajtrajška mužnosti. Po tomto najúteššnejšom zo žiaľov nezostane v živote nič, čo by nedokázal nejako zniesť.",
  "01-26": "Vznešení psi majú povahu byť mierní k tým, ktorých poznajú, a opačnú k tým, ktorých nepoznajú. Ako teda môže byť pes niečím iným ako milovníkom poznania, keď rozoznáva to, čo je jeho vlastné, od toho, čo je cudzie?",
  "01-27": "Najmilšou bytosťou na svete je mokrý pes.",
  "01-28": "Žiadni filozofi nás nechápu tak dôkladne ako psi a kone. Prehliadnu nás na prvý pohľad.",
  "01-29": "Dvakrát nerozmýšľam nad tým, že pozbieram trus svojho psa — ale keď leží vedľa neho trus cudzieho psa, pomyslím si: „Fuj, psí trus!\"",
  "01-30": "Puto s pravým psom je trvalé tak, ako sú trvalé pominuteľné putá tohto sveta.",
  "01-31": "Myslíte si, že psi nebudú v nebi? Hovorím vám — budú tam dávno pred nami.",
  "02-01": "Neexistuje žiadna vernosť, ktorá by nikdy nebola porušená, okrem vernosti skutočne verného psa.",
  "02-02": "Na svete nie je psychiater ako šteňa, ktoré ti olizuje tvár.",
  "02-03": "My, čo sa rozhodujeme obklopiť životmi ešte pominuteľnejšími ako je ten náš, žijeme vo vnútri krehkého kruhu, ľahko a často trhaného. Hoci nedokážeme prijať jeho bolestné medzery, nechceli by sme žiť inak. Cherujeme pamäť ako jedinú istú nesmrteľnosť, nikdy celkom nepochopiac nevyhnutný plán.",
  "02-04": "Psy sa smejú, ale smejú sa chvostom.",
  "02-05": "Pohladkať, poškrabkať a pomaznať psa môže byť pre myseľ i srdce rovnako upokojujúce ako hlboká meditácia — a pre dušu takmer rovnako dobré ako modlitba.",
  "02-06": "Môj malý pes — tlkot srdca pri mojich nohách.",
  "02-07": "Pes nepotrebuje luxusné autá, veľké domy ani značkové oblečenie. Postačí mu mokrá palica z potoka. Psovi nezáleží na tom, či si bohatý alebo chudobný, bystrý alebo tupý, múdry alebo hlúpy. Daj mu svoje srdce a on ti dá svoje.",
  "02-08": "Aby sme si psa naozaj vychutnali, nestačí ho len trénovať, aby bol napoly ľudský. O to ide — otvoriť sa možnosti, že sa sami staneme sčasti psom.",
  "02-09": "Neber psovo obdivovanie ako presvedčivý dôkaz toho, že si skvelý.",
  "02-10": "Keby nás mimozemšťania videli venčiť psov a zbierať ich výkaly, kto by bol podľa nich pánom?",
  "02-11": "Za peniaze si môžeš kúpiť dobrého psa, ale len láska ho prinúti mávať chvostom.",
  "02-12": "Keď príde posledná chvíľa a smrť vezme pána do náručia a jeho telo uložia do chladnej zeme — nech všetci ostatní priatelia odídu svojou cestou — pri hrobe ho nájdete vznešeného psa, hlavu medzi labami, oči smutné, no otvorené v bdelej stráži, verného a pravého až do smrti.",
  "02-13": "Môj pes vie, že som človek, a zmysel tohto slova nenájdete v žiadnej knihe napísaný tak jasne, ako je napísaný v jeho duši.",
  "02-14": "Psy nie sú celý náš život, ale robia náš život celým.",
  "02-15": "Súcit so zvieratami je úzko spätý s dobrotou charakteru a smelo možno tvrdiť, že ten, kto je krutý k živým tvorom, nemôže byť dobrým človekom.",
  "02-16": "Priemerný pes je milší človek ako priemerný človek.",
  "02-17": "Ak raz odídem od tých, ktorých milujem, na Tichú cestu, neplačte, nespomínajte ma so slzami — smejte sa a rozprávajte o mne, akoby som bol stále pri vás.",
  "02-18": "Psovi môžete povedať hocijakú hlúposť a on sa na vás pozrie s výrazom, ktorý hovorí: „Wow, máš pravdu! To by ma nikdy nenapadlo!\"",
  "02-19": "Zo samotného života prichádza dosť smútku, aby naplnil naše dni; no keď sme si istí, že nás smútok čaká, prečo si ho zariaďujeme naviac? Bratia a sestry, varujte sa dávať srdce psovi, aby ho roztrhol.",
  "02-20": "Kúp si šteňa a tvoje peniaze kúpia lásku bez zaváhania.",
  "02-21": "Nezaujíma ma náboženstvo muža, ak sa od neho jeho pes a mačka nemajú lepšie.",
  "02-22": "Psy sú pevne presvedčené, že musia vždy ísť s vami v aute — pre prípad, keby bolo treba prudko štekoť na nič priamo do ucha.",
  "02-23": "Na psovi, ktorý chce raňajky, niet tlačidla odloženia budíka.",
  "02-24": "Sme sami, absolútne sami na tejto náhodnej planéte; a zo všetkých foriem života, ktoré nás obklopujú, jedine pes s nami uzavrel spojenectvo.",
  "02-25": "Pes je džentlmen; dúfam, že pôjdem do jeho neba, nie do ľudského.",
  "02-26": "Nevolá sa už Divoký pes, ale Prvý Priateľ, lebo bude naším priateľom navždy a navždy a navždy.",
  "02-27": "Na tomto mieste spočívajú pozostatky toho, kto mal krásu bez márnivosti, silu bez drzosti, odvahu bez krutosti a všetky cnosti človeka — bez jeho nerestí.",
  "02-28": "Pes je boh radovánok.",
  "03-01": "Ak chceš v dome to najlepšie miesto, premiestnite psa.",
  "03-02": "Psy nikdy nerozprávajú o sebe, ale počúvajú ťa, keď hovoríš o sebe, a udržiavajú zdanie, že ich rozhovor zaujíma.",
  "03-03": "Nemusíme si získavať jeho dôveru ani priateľstvo: rodí sa ako náš priateľ; kým má ešte zatvorené oči, už verí v nás: dokonca ešte pred narodením sa odovzdal človeku.",
  "03-04": "Keď sa pyšný syn ľudský vracia do zeme, sláve neznámy, hoc rodom nesený, sochárske umenie vyčerpá pompéznosť žiaľu a ozdobené urny zaznamenajú, kto odpočíva nižšie. Ale úbohý pes, v živote najvernejší priateľ, prvý, čo vítaval, najrýchlejší v obrane.",
  "03-05": "Akýkoľvek muž s peniazmi na kúpu sa môže stať majiteľom psa. Ale žiaden muž — nech minie akokoľvek veľa peňazí, jedla a taktiky — sa nemôže stať Pánom psa bez súhlasu samotného psa.",
  "03-06": "Ak k vám pes nepríde po tom, čo sa vám pozrel do tváre, mali by ste ísť domov a preskúmať svoje svedomie.",
  "03-07": "Niektoré dni si pes, niektoré dni si hydrant.",
  "03-08": "Zistil som, že keď ťa trápi niečo hlboko, dostaneš od tichej oddanej spoločnosti psa niečo, čo nedostaneš od nikoho iného.",
  "03-09": "Keď raz máš úžasného psa, život bez neho je život ochudobnený.",
  "03-10": "Kúp si šteniatko a tvoje peniaze kúpia lásku neochvejnú, ktorá nemôže klamať — dokonalú vášeň a zbožňovanie živené kopancom do rebier alebo pohladením po hlave.",
  "03-11": "PES, príd. Akýsi doplnkový alebo podriadený Božský, navrhnutý na zachytenie prebytku a nadbytku svetskej úcty.",
  "03-12": "Najväčšia radosť z psa je tá, že sa pri ňom môžeš urobiť bláznom, a nielenže ťa neokríkne, ale aj on sa urobí bláznom.",
  "03-13": "Psy sú otrasní pokrčkáči. Keď dostanú dobrú kartu, vrtia chvostom.",
  "03-14": "Keď psy skáču na tvoju posteľ, je to preto, že ťa zbožňujú. Keď to isté robia mačky, je to preto, že ich zaujíma vôňa tvojho vankúša.",
  "03-15": "Psy ti dajú bezpodmienečnú lásku až do posledného dňa svojho života. Mačky ti dajú zaplatiť za každú chybu, ktorú si kedy urobil od chvíle, keď si sa narodil.",
  "03-16": "Sotva možno pochybovať, že láska k človeku sa stala u psa inštinktívnou.",
  "03-17": "Carnegie, Vanderbilt a Astor spolu nedokázali by nazbierať dosť peňazí, aby kúpili štvrtinový podiel na mojom malom psovi.",
  "03-18": "Psy, keď sa stretnú na ulici, netrpia konvenciou, ktorá núti ľudí predstierať ľahostajnosť jeden k druhému.",
  "03-19": "Ten, kto hovoril ‚nechaj spiaceho psa spať', nespal so psami.",
  "03-20": "Sám človek nedokáže vyjadriť lásku a pokoru vonkajšími znakmi tak zreteľne ako pes, keď so sklopenými ušami, visiacimi perami, poddajným telom a vrtiacim sa chvostom stretáva svojho milovaného pána.",
  "03-21": "A tak Argos ležal tam, zamorený blchami. A keď vycítil, že Odyseus stojí nablízku, zavrtil chvostom a sklopil uši dolu, hoci už nemal silu potiahnuť sa bližšie k svojmu pánovi.",
  "03-22": "Puto s psom je také trvalé, aké len puto tohto sveta môže byť.",
  "03-23": "Čím viac vidím ľudí, tým viac sa mi páči môj pes.",
  "03-24": "Psy neraccionalizujú. Nechávajú si nič za zlé. Nevidia vonkajšok človeka, ale jeho vnútro.",
  "03-25": "Toho, koho pes raz bezvýhradne prijme za Pána, je navždy Bohom tohto psa.",
  "03-26": "Štekaví psi príležitostne hrýzajú, ale smejúci sa ľudia takmer nikdy nestrieľajú.",
  "03-27": "Vernosť psa je vzácny dar, ktorý si vyžaduje nemenej záväzné morálne zodpovednosti ako priateľstvo človeka.",
  "03-28": "Môj pes zomrel. / Pochoval som ho v záhrade / vedľa zhrdzaveného starého stroja.",
  "03-29": "Dejiny sú plné príkladov vernosti psov viac ako vernosti priateľov.",
  "03-30": "Môj pes vie štekat ako kongresman, aportovať ako asistent, prosiť ako hovorca a hrať mŕtveho ako recepčná, keď zazvoní telefón.",
  "03-31": "Pes je náboženský tvor. Vo svojom divom stave uctíva mesiac a svetlá plávajúce na vode. To sú jeho bohovia, ktorým sa v noci prihovára dlhými vytím.",
  "04-01": "Možno máš psa, ktorý si nesadne, neprevráti sa, ani ti nenavarí raňajky — nie preto, že by bol príliš hlúpy to naučiť sa, ale preto, že je príliš múdry, aby sa obťažoval.",
  "04-02": "Sú traja verní priatelia — stará manželka, starý pes a hotové peniaze.",
  "04-03": "Áno, verím v nebo, do ktorého nikdy nevstúpim. Verím v nebo pre celý psí rod, kde môj pes čaká na môj príchod a láskavo máva chvostom ako vejárom.",
  "04-04": "V celých dejinách sveta je jediná vec, ktorú za peniaze nekúpiš — totiž vrtenie psieho chvosta.",
  "04-05": "Začni škriabať psa a nájdeš si trvalú robotu.",
  "04-06": "Pamätaj, že Všemohúci, ktorý dal psovi byť spoločníkom našich radostí i strázní, obdaril ho povahou ušľachtilou a neschopnou klamu.",
  "04-07": "Moja módna filozofia znie: ak nie si pokrytý psou srsťou, tvoj život je prázdny.",
  "04-08": "Verne, oddane a neodvolateľne uznal nadradenosť človeka a odovzdal mu sa celou dušou i telom, bez zadných myšlienok, bez akéhokoľvek úmyslu vrátiť sa späť.",
  "04-09": "Nešťastím pri chovaní psa je, že tak skoro umiera. Ale keby žil päťdesiat rokov a potom umrel, čo by sa stalo so mnou?",
  "04-10": "Je našim dôverným a zanietením otrokom, ktorého nič neodradí, nič neodpudí, ktorého horlivá dôvera a láska sú nezničiteľné.",
  "04-11": "Psy nám dali absolútne všetko. Sme stredom ich vesmíru, sme ohniskom ich lásky, viery a dôvery. Slúžia nám za odrobinky. Je to nepochybne najlepší obchod, aký človek kedy uzavrel.",
  "04-12": "Keby som bol čo len napoly taký človek ako môj pes, bol by som dvakrát väčší človek, ako som.",
  "04-13": "Boh si na chvíľu sadol, keď bol pes hotový, aby sa na neho pozrel a vedel, že je dobrý, že nechýba nič, že nemohol byť stvorený lepšie.",
  "04-14": "Pre svojho psa je každý človek Napoleon — odtiaľ tá trvalá obľuba psov.",
  "04-15": "Pes má v živote jeden cieľ — darovať svoje srdce.",
  "04-16": "Nie je psa, čo sa hrá a beháva, z ktorého by sme sa neučili. Ten druhý pes — ten, čo celý život chodí na vôdzke poslušne po chodníku — je to, čím je stolička pre strom.",
  "04-17": "S okom vzpriameným, aby zachytil pohľad pána — radosť, útecha a opora človeka: strážca boháča a priateľ chudobného, jediný tvor verný až do konca.",
  "04-18": "Psy nás učia jednu veľmi dôležitú životnú lekciu: poštárovi sa nedá veriť.",
  "04-19": "Nikto nesie taký hlboký obdiv k osobitnej genialite tvojho rozhovoru ako tvoj pes.",
  "04-20": "Psy sú vodcami tejto planéty. Ak vidíš dve živé bytosti, pričom jedna robí hromadu a druhá ju za ňou nesie, ktorú by si považoval za šéfa?",
  "04-21": "Psy vstupujú do našich životov, aby nás učili o láske a vernosti. Odchádzajú, aby nás učili o strate. Nový pes nikdy nenahrádza starého — iba rozširuje srdce.",
  "04-22": "Tu leží ten, kto nás miloval a koho sme milovali. Nech je môj spánok akokoľvek hlboký, začujem ťa — a nijaká moc smrti nezadrží môjho ducha, aby nevrtial vďačným chvostom.",
  "04-23": "Kto nikdy nemal psa, nemôže vedieť, čo znamená milovať a byť milovaný.",
  "04-24": "Výchova nie je o tom, ukázať psovi, kto je pánom; je o prevzatí zodpovednosti za živú bytosť, ktorú si priviedol do svojho sveta.",
  "04-25": "Tisíckrát mi povedal, že som jeho dôvodom existencie — tým, ako sa opiera o moju nohu, tým, ako búcha chvostom pri najmenšom mojom úsmeve.",
  "04-26": "Vďaka radosti psa rastie aj naša vlastná. Nie je to malý dar. Nie je to najmenší dôvod, prečo by sme mali s láskou ctiť psa svojho života, psa zo susednej ulice i všetkých psov ešte len nenarodených.",
  "04-27": "Pes je učiteľ života, ktorý nás učí princípom najdôležitejších morálnych hodnôt: čestnosti, integrity, vernosti, dôvery, úcty a lásky.",
  "04-28": "Ach, kopeš na mojom hrobe, / moja milá? — sadíš rutu? ... / Ó, to som ja, moja drahá pani, / tvoj malý pes, čo stále blízko bdí.",
  "04-29": "Zvieratá znamenajú v našich životoch toľko. Na čo sa v živote môžeme spoľahnúť? Na psa alebo mačku, ktorí nás milujú bezpodmienečne, každý deň, s nesfalšovanou vernosťou.",
  "04-30": "Čítaním psa sa stáva veľmi zreteľným, aký stabilný alebo nestabilný je jeho ľudský spoločník. Naši psi sú naše zrkadlá.",
  "05-01": "Moje psy ma nasledujú preto, lebo chcú — nie preto, lebo sa boja, čo sa stane, ak nebudú.",
  "05-02": "Psy neklamú — a prečo by som klamal ja? Keď prídu cudzinci, vrčia a štepia; svojich milovaných spoznajú aj v tme. Nechaj ma teda, vo dne v noci, byť rovnako plný pravdy ako oni.",
  "05-03": "Teraz Flush vedel, čo ľudia nikdy vedieť nemôžu — lásku čistú, lásku prostú, lásku celú; lásku, ktorá so sebou nevlečie starosť; ktorá nemá hanby; nemá výčitiek; ktorá je tu a je preč, ako včela na kvete — tu je a preč je.",
  "05-04": "Tento vojak, uvedomil som si, musel mať doma priateľov aj vo svojom pluku; a predsa ležal opustený od všetkých — okrem svojho psa. Pozeral som sa bez pohnutia na bitky, ktoré rozhodovali o osude národov. Bez slzy som vydával rozkazy, ktoré priniesli smrť tisíckam. A tu som bol pohnutý — hlboko pohnutý, pohnutý až k slzám. A čím? Žiaľom jedného psa.",
  "05-05": "Dal som svojej bolesti meno a volám ju ‚pes' — je rovnako verná, rovnako dotieravá a bezočivá, rovnako zábavná, rovnako bystrá ako každý iný pes, a môžem na ňu nadávať a vybíjať si na nej zlú náladu.",
  "05-06": "Verím v integritu. Psy ju majú. Ľuďom niekedy chýba.",
  "05-07": "Radostný, radostný, radostný, ako len psy vedia byť šťastné — v slobode svojho hanby zbaveného ducha.",
  "05-08": "Skrze neho som odvtedy ako cez okno hľadel s hlbším súcitom na všetkých svojich smrteľných blížnych.",
  "05-09": "Pes je most medzi cudzincami.",
  "05-10": "Nebo nebude nikdy Nebom, ak ma môj pes neuvíta tam.",
  "05-11": "Jediný, absolútny a najlepší priateľ, akého má človek na tomto sebeckom svete — jediný, ktorý ho nezradí ani sa ho nezriekne — je jeho pes.",
  "05-12": "My ľudia môžeme byť brilantní a môžeme byť výnimoční, no stále sme spojení so zvyškom života. Nikto nám to nepripomína lepšie ako naše psy.",
  "05-13": "Zaujíma ma, či si ostatné psy myslia, že pudlíky sú členmi nejakej podivnej náboženskej sekty.",
  "05-14": "Čo robia psy vo voľný deň? Nemôžu povaľovať sa — to je predsa ich práca!",
  "05-15": "Svojho psa som pomenoval ‚Zostaň', aby som mohol hovoriť: ‚Poď sem, Zostaň! Poď sem, Zostaň.'",
  "05-16": "Domov je tam, kde ťa pes vybehne privítať.",
  "05-17": "Správne vycvičený človek môže byť najlepším priateľom psa.",
  "05-18": "Ľudstvo priťahujú psy, lebo sú tak podobní nám samým — nemotorní, láskavý, zmätení, ľahko sklamaní, dychtivý po pobavení, vďační za láskavosť.",
  "05-19": "Ak si myslíte, že psy nevedia počítať, skúste si dať do vrecka tri psie sušienky a potom mu dajte len dve.",
  "05-20": "V manželstve sa ťažko vydrží. Moja žena bozkáva psa na pery, ale zo môjho pohára sa napiť nechce.",
  "05-21": "Všimli ste si niekedy, že keď fúknete psovi do papule, nahnevá sa na vás? No keď ho veziete autom, vystrčí hlavu z okna.",
  "05-22": "Nebo je miesto, kde vás prídu privítať všetky psy, ktoré ste kedy milovali.",
  "05-23": "Ľudia učia psa sadnúť si — je to trik. Ja sedím celý život a žiadny pes sa na mňa nikdy nepozrel tak, akoby si myslel, že som vychytralý.",
  "05-24": "Psy sú lepšie ako ľudia, lebo vedia, ale neprezradia.",
  "05-25": "Stalo sa vám niekedy, že ste vošli do izby a zabudli, prečo ste vošli? Myslím, že takto trávia psy celý život.",
  "05-26": "Môj pes je napoly pitbull, napoly pudlík. Strážny pes z neho moc nie je, ale klebety roznáša zlovestne.",
  "05-27": "Dobre vychovaný pes sa nepokúsi deliť s vami obed. Len vás prinúti cítiť sa natoľko vinným, že si ho nemôžete vychutnať.",
  "05-28": "Dobrý pes nikdy neumiera; stále ostáva, kráča vedľa vás v chladných jesenných dňoch, keď mráz leží na poliach a zima sa blíži — so hlavou vo vašej dlani tak, ako kedysi.",
  "05-29": "Chcete priateľa vo Washingtone? Zadovážte si psa.",
  "05-30": "Bol krásou bez márnomyseľnosti, silou bez drzosti, odvahou bez krutosti a všetkými cnosťami človeka bez jeho chýb.",
  "05-31": "Aby si každý zachoval správnu perspektívu o vlastnej dôležitosti, mal by mať psa, ktorý ho bude zbožňovať, a mačku, ktorá ho bude ignorovať.",
  "06-01": "Psy prídu, keď ich zavoláš; mačky si vezmú odkaz a ozvú sa neskôr.",
  "06-02": "Majitelia psov si určite všimli, že ak im poskytneš jedlo, vodu, prístrešie a náklonnosť, budú si myslieť, že si boh. Kým majitelia mačiek sú nútení konštatovať, že ak mačkám poskytnú jedlo, vodu, prístrešie a náklonnosť, mačky z toho vyvodia, že bohmi sú ony.",
  "06-03": "Možno to nie sú hviezdy, ale skôr otvory v nebi, cez ktoré prúdi láska tých, ktorých sme stratili, a svieti na nás, aby nám dala vedieť, že sú šťastní.",
  "06-04": "Keď je najlepším priateľom muža jeho pes, ten pes má problém.",
  "06-05": "Ani jeden nie je nespokojný, ani jeden nie je posadnutý mánií vlastníctva.",
  "06-06": "Keby zvieratá vedeli hovoriť, pes by bol priamočiary a neopatrný v slovách; no mačka by oplývala vzácnou schopnosťou nikdy nepovedať ani slova navyše.",
  "06-07": "Ľudia, čo chovajú psov, sú zbabelci, ktorí si sami netrúfajú hrýzť.",
  "06-08": "Každý, kto nevie, ako chutí mydlo, ešte nikdy neumýval psa.",
  "06-09": "Keď raz spoznáš výnimočného psa, život bez neho je životom ochudobneným.",
  "06-10": "Psy sú moje obľúbené vzory. Chcem pracovať ako pes — robiť to, na čo som sa narodila, s radosťou a zmyslom. Chcem sa hrať ako pes — s úplným a bezstarostným zanietením. Chcem milovať ako pes — s otvorenou oddanosťou a bez akéhokoľvek záujmu o to, čo ľudia robia, koľko zarábajú alebo koľko vážia.",
  "06-11": "Medzi nimi zíval najhlbší priepasť, aká môže oddeliť dve bytosti. Ona hovorila. On bol nemý. Ona bola žena; on bol pes.",
  "06-12": "Pes túži po náklonnosti viac ako po večeri. No — takmer.",
  "06-13": "Veľká radosť so psom spočíva v tom, že môžeš zo seba urobiť blázna, a on ťa nielen neokríkne, ale urobí zo seba blázna tiež.",
  "06-14": "Život je ako tím psích záprahov. Ak nie si vodčí pes, krajina sa nikdy nemení.",
  "06-15": "Naše domáce zvieratá majú pri nás stráviť taký krátky život — a väčšinu z neho strávia čakaním na nás.",
  "06-16": "Myslím, že psy sú tie najúžasnejšie tvory; milujú bezpodmienečne. Pre mňa sú vzorom toho, čo znamená byť nažive.",
  "06-17": "Psy sú múdrejšie ako ľudia. Neprikladajú veciam veľkú váhu. Nezabíjajú čas hromadením majetku.",
  "06-18": "Psy majú neobmedzenú nadšenosť, no žiadny zmysel pre hanbu. Mal by som mať psa ako životného kouča.",
  "06-19": "Keď pes máva chvostom a súčasne šteká, ktorému koncu vlastne veriť?",
  "06-20": "Raz som sa rozhodla, že s chlapom nebudem chodiť, pretože nebol nadšený zo stretnutia s mojím psom. Bolo to pre mňa asi tak, ako keby nechcel spoznať moju mamu.",
  "06-21": "Ak v Nebi nie sú žiadne psy, chcem po smrti ísť tam, kde sú oni.",
  "06-22": "Od psa sa človek vie veľa naučiť — aj od takého bláznivého, ako bol ten náš. Marley ma naučil žiť každý deň s nevzdúvateľnou búrlivosťou a radosťou, využívať každú chvíľu a nasledovať srdce.",
  "06-23": "Pes je „akýsi dodatočný či vedľajší Boh, stvorený na to, aby zachytával prebytok a nadmeru uctievania tohto sveta.\"",
  "06-24": "Psy sú ako čipsy. Ťažko sa zastaviť pri jednom.",
  "06-25": "Podozrievavo sa pozerám na ľudí, ktorí nemajú radi psov, ale verím psovi, keď sa mu niekto nepáči.",
  "06-26": "Keď ti osemdesiatpäťkilový cicavec olíže slzy a potom sa ti pokúsi sadnúť na kolená, ťažko sa cítiš smutne.",
  "06-27": "Pes je jediná vec, ktorá dokáže záplatovať prasklinu v zlomenom srdci.",
  "06-28": "Psy sú múdre. Odplazia sa do tichého kúta, olížu si rany a nevráťa sa do sveta, kým nie sú opäť celé.",
  "06-29": "Ak muž nevyjde rýchlo za myšlienku „Čo mi tento pes prinesie?\" do širokého stavu prostej radosti z bytia so psom, nikdy nespozná samotnú podstatu toho spoločenstva, ktoré nezávisí od psích vlastností, ale od akéhosi podivného a jemného splývania nemých duchov.",
  "06-30": "Keby psy vedeli hovoriť, ubralo by to veľa zábavy z ich vlastnenia.",
  "07-01": "Pes je jeden z posledných dôvodov, pre ktoré sa niektorých ľudí dá ešte presvedčiť, aby vyšli na prechádzku.",
  "07-02": "Kto tvrdí, že šťastie sa nedá kúpiť, zabudol na šteňatá.",
  "07-03": "Nebo je miesto, kde ťa prídu privítať všetky psy, ktorých si v živote miloval.",
  "07-04": "Vzťah medzi psom a človekom je vždy zložitý — spojenie zahalené osobnou históriou, temperamentom, skúsenosťou, inštinktom a láskou.",
  "07-05": "Aký napätý a ustaraný život musia psy viesť — citovo tak prepojené so svetom ľudí, ktorých náklonnosť sa bez prestania usilujú získať, ktorých autorite majú bez otázok poslúchať a ktorých mysle nikdy nedokážu pochopiť viac než len nedokonale.",
  "07-06": "Pes je dokonalý model. Nesťažuje sa a nežiada zálohy.",
  "07-07": "Zamysleli ste sa niekedy nad tým, čo si o nás musia myslieť naše psy? Vraciame sa z obchodu s neuveriteľnou korisťou — kurča, bravčové, pol kravy. Musia nás považovať za najlepších lovcov na svete!",
  "07-08": "Psy sú úžasné tvory, ale sú proslávené tým, že minú pointu.",
  "07-09": "Riešte každú situáciu ako pes. Ak to nemôžete zjesť ani sa s tým hrať, jednoducho na to počuráte a odídete.",
  "07-10": "Nikto nemôže plne pochopiť zmysel lásky, pokiaľ nemal psa. Pes vám dokáže prejaviť úprimnejšiu náklonnosť jediným mávaním chvosta než človek za celý život podaných rúk.",
  "07-11": "Psy čítajú svet nosom a svoju históriu píšu v moči.",
  "07-12": "Veľa útulkových psov sú kríženci — tak ako ja.",
  "07-13": "Prídem domov na konci dňa a nechce sa mi hovoriť. Chcem len ľahnúť na podlahu a pohladkať svojich psov a mačky.",
  "07-14": "Skvelá vec na vlastnení psa je, že vás akosi núti byť prítomní v danej chvíli — lebo práve tam pes trávi celý čas.",
  "07-15": "Niektorí z mojich najlepších hereckých partnerov boli psy a kone.",
  "07-16": "V rôznych vzťahoch ma obvinili, že milujem svojho psa viac ako toho, s kým som.",
  "07-17": "Kde nájdeš cit / spomedzi ľudských bytí / verný ako pes!",
  "07-18": "Moja tragédia je, že po celý život túžim po psovi, a predsa ma prekliali mačkami.",
  "07-19": "Nie je rozhodujúce, aký veľký je pes v boji — rozhodujúce je, aký veľký boj je v psovi.",
  "07-20": "Ak ste zdieľali život so psom, ako som to robila ja v Bournemouthe, alebo s mačkou, viete dokonale dobre, že zvieratá majú osobnosť, myseľ a city.",
  "07-21": "Niektoré z našich najväčších historických a umeleckých pokladov zverujeme kurátori v múzeách; iné brávame na prechádzku.",
  "07-22": "Bratia a sestry, dajte si pozor / srdce psovi nedávajte na roztorhanie.",
  "07-23": "Skutočne spoločenský a nenahraditeľný pes je náhodou prírody. Nevyšľachtíte ho a nekúpite za peniaze. Jednoducho sa objaví.",
  "07-24": "Život je séria psov.",
  "07-25": "Kým psa nemáte, nedokážete si celkom predstaviť, aké je to s ním žiť; keď ho máte, nedokážete si predstaviť, ako ste žili inak.",
  "07-26": "Najväčší strach, ktorý psy poznajú, je strach, že sa nevrátite, keď odídete von bez nich.",
  "07-27": "Všetky psy sú vynikajúce v zachytávaní i tých najnepatrnejších pohybov, ktoré robíme — a predpokladajú, že každý malý pohyb niečo znamená.",
  "07-28": "Kúp si šteňa a za peniaze dostaneš / lásku neochvejnú, čo klamať nevie — / dokonalú vášeň a úctu živenú / kopom do rebier alebo pohladením po hlave.",
  "07-29": "Spoločnosť krotí vlka na psa. A človek je zo všetkých tvor najskrotnejší.",
  "07-30": "Psy čuchom vnímajú čas. Minulosť leží pod nohami — vône včerajška sa usadili na zemi.",
  "07-31": "Podľa štandardných testov inteligencie psy pri rébus zlyhali. Ja naopak verím, že uspeli veľkolepým spôsobom. Použili na úlohu nový nástroj. Tým nástrojom sme my.",
  "08-01": "Verím, že dosiahneme oveľa viac, ak psu poskytneme dobré životné skúsenosti. Radšej viem, že pes chodí za mnou preto, že chce — nie preto, že sa bojí, čo sa stane, ak nepôjde.",
  "08-02": "Buď pri práci so psami používate metódy a pomôcky, ktoré spôsobujú bolesť, strach a zámerné nepohodlie — alebo nie. Ja nie.",
  "08-03": "Teraz Flush vedel to, čo ľudia nikdy nemôžu vedieť — lásku čistú, lásku prostú, lásku celú; lásku, ktorá so sebou nenesie žiaden vlak starostí; ktorá nepozná hanbu ani výčitky.",
  "08-04": "Múdry muž, ktorý sa stýka s nerestnými, stáva sa hlupákom; pes, ktorý cestuje s dobrými ľuďmi, stáva sa rozumnou bytosťou.",
  "08-05": "Politika mi je cudzia. Neviem sa stotožniť ani s liberálmi, ani s konzervatívcami. Psy žijú v mierke, ktorej rozumiem.",
  "08-06": "Psy hovoria — ale iba s tými, ktorí vedia počúvať.",
  "08-07": "Myslím, že by som sa obrátil a žil so zvieratami, sú také pokojné a sebestačné, / Stojím a dlho, dlho sa na ne dívam.",
  "08-08": "Nepotia sa a nevzdychajú nad svojím údelom, / Neležia v noci hore v tme a neplačú za svoje hriechy.",
  "08-09": "Milá priateľka, dar tej jedinej, / ktorá svoju pravú vernosť zachovala, / prešla tvojou nižšou podstatou; / Nech moje požehnanie je vypovedané / s rukou položenou na tvojej hlave, / nežné spoločné stvorenie!",
  "08-10": "Lepšie byť psom v čase mieru ako človekom v čase nepokojov.",
  "08-11": "Pes mi kladie otázku a ja nemám odpoveď. Prelieta krajinou a pýta sa ma bez slov, a jeho oči sú dve vlhké otázniky.",
  "08-12": "Len tento pes čakal, / vediac, že keď svetlo odíde, / láska zostáva — a svieti.",
  "08-13": "Miloval celým srdcom a odmietol zľacovať seba i svoju lásku.",
  "08-14": "Keď v studených tichých nociach namieril čumák k hviezde a dlho, vlčím spôsobom výl, boli to jeho predkovia, mŕtvi a popol, čo namierili čumák k hviezde a vyľ naprieč storočiami a skrze neho.",
  "08-15": "Zvieratá sú takí príjemní priatelia — nepýtajú sa, nekritizujú.",
  "08-16": "Štekot psa nevyrušuje muža na ťave.",
  "08-17": "Existuje extáza, ktorá znamená vrchol života a nad ktorú život nemôže stúpnuť. A taký je paradox života: táto extáza prichádza vtedy, keď je človek nažive najviac, a prichádza ako úplné zabudnutie na to, že je nažive.",
  "08-18": "Som pes Jeho Výsosti v Kew; / Povedzte mi, pane, čí ste vy pes?",
  "08-19": "Pes k vám príde a žije s vami v dome, no preto ho nevlastníte — tak ako nevlastníte dážď, ani stromy, ani zákony, ktoré sa ich týkajú.",
  "08-20": "Pravdu nenatínam ani nezkreslím, / keď tvrdím, že pes je plný lásky. / Zistil som tiež, po vlastnej skúške, / že mokrý pes miluje najväčšmi.",
  "08-21": "Veru nie najľahšou vecou, keď nás opustia títo tichí priatelia, je, že so sebou odnášajú toľko rokov nášho vlastného života.",
  "08-22": "Najlepšia vec na mužovi je jeho pes.",
  "08-23": "Nikto nemôže dať druhému dar idyly; len zviera to dokáže, pretože len zvieratá neboli vyhnané z raja.",
  "08-24": "Psy nikdy neboli vyhnané z raja. Karenin nevedel nič o dualite tela a duše a nepoznal pojem znechutenia.",
  "08-25": "Psí čas sa nedá vykresať po priamke; nepostupuje od jednej veci k ďalšej. Pohybuje sa v kruhu ako ručičky hodín.",
  "08-26": "Každý pes má svoj deň.",
  "08-27": "Tak sa bojím ľudských slov. Opisujú všetko tak presne: a toto nazývajú psom a tamto domom, tu začiatok a tam koniec.",
  "08-28": "Do neba sa ide na základe priazne. Keby sa šlo na základe zásluh, zostali by ste vonku a váš pes by vošiel dnu.",
  "08-29": "Naše lásky nie sú darované, len požičané, / na zložený úrok cent za cent.",
  "08-30": "Plot vydrží tri roky, pes tri ploty, kôň troch psov a človek troch koní.",
  "08-31": "Dokonca aj strašné mučeníctvo si musí odbyť svoju cestu / tak či tak v nejakom kúte, nejakom neupravenom mieste, / kde psy pokračujú vo svojom psacom živote.",
  "09-01": "Hladný pes neverí ničomu okrem mäsa.",
  "09-02": "Dobrý človek sa bude cítiť vinný aj pred psom.",
  "09-03": "Je mojimi druhými očami, ktoré vidia nad oblaky; mojimi druhými ušami, ktoré počujú nad vetry. Tisíckrát mi povedal, že som jeho dôvodom existencie — spôsobom, akým sa opiera o moju nohu, spôsobom, akým máva chvostom pri mojom najmenšom úsmeve.",
  "09-04": "Naučil ma, čo znamená oddanosť. S ním poznám tajomné útočište a súkromný pokoj. Priniesol mi pochopenie tam, kde som bol predtým nevedomý.",
  "09-05": "Ak je muž veľký, aj jeho pes bude nosiť hrdý výraz.",
  "09-06": "Nikdy naozaj nevlastníme psa tak, ako on vlastní nás.",
  "09-07": "Nikto nedokáže plne pochopiť zmysel lásky, pokiaľ nemal psa. Pes vám dokáže ukázať viac úprimnej náklonnosti jediným zamávaním chvosta, než dokáže človek zhromaždiť za celý život podaní rúk.",
  "09-08": "Hodiť kosť psovi nie je dobročinnosť. Dobročinnosť je kosť, o ktorú sa podelíte so psom, keď ste práve tak hladný ako on.",
  "09-09": "Prečo človeka napĺňa šťastím sledovať, ako pes je prostě psom?",
  "09-10": "Láska, láska, láska, hovorí Percy. A ponáhľaj sa čo najrýchlejšie po žiariacej pláži, alebo po rumovišti, alebo prachu. Potom zaspi. Vzdaj sa tepla svojho tela, svojho bijúceho srdca. Potom dôveruj.",
  "09-11": "Mýliť sa je ľudské — odpúšťať je psie.",
  "09-12": "Percy sa zatiaľ opiera o mňa a hľadí mi do tváre. Akoby som bol práve taký úžasný ako dokonalý mesiac.",
  "09-13": "Ak v nebi nie sú psy, chcem po smrti ísť tam, kde oni šli.",
  "09-14": "Najväčšia láska je materská; potom psie; potom milencova.",
  "09-15": "Psy v skutočnosti neuprednostňujú kosti pred mäsom; jednoducho im nik nikdy mäso nedáva.",
  "09-16": "Ak sa zastavíš vždy, keď pes zašteká, tvoja cesta nikdy neskončí.",
  "09-17": "Pes má toľko priateľov preto, lebo máva chvostom namiesto jazyka.",
  "09-18": "V dokonalom svete by mal každý pes domov a každý domov by mal psa.",
  "09-19": "Ak si hostiteľom svojho hosťa, buď hostiteľom aj jeho psa.",
  "09-20": "Nevolaj psa s bičom v ruke.",
  "09-21": "Jeden pes zahreší na niečo; ostatní šteká naňho.",
  "09-22": "Tichý pes hrýzie ako prvý.",
  "09-23": "Nie je náhoda, že najlepší priateľ človeka nevie hovoriť.",
  "09-24": "Psy veria, že sú ľudia. Mačky veria, že sú bohovia.",
  "09-25": "Dom bez mačky alebo psa je domom darebáka.",
  "09-26": "Trom veciam sa nedá veriť: kraviemu rohu, psím zubom a konskému kopytu.",
  "09-27": "Psy majú majiteľov, mačky majú personál.",
  "09-28": "Pes dokáže chvostom za pár minút vyjadriť viac, než jeho majiteľ jazykom za hodiny.",
  "09-29": "Môj slnečný svit neprichádza z neba — prichádza z lásky v psích očiach.",
  "09-30": "Mať psa ťa obdarí mnohými z najšťastnejších dní tvojho života — a jedným z najhorších.",
  "10-01": "Jeden z dôvodov, prečo je pes takou útechou, keď ti je smutno, je ten, že sa nesnaží zistiť prečo.",
  "10-02": "Ak sa tvoj pes niekomu nepáči, pravdepodobne by si ho nemal mať rád ani ty.",
  "10-03": "Ak je tvoj pes tučný, ty nemáš dostatok pohybu.",
  "10-04": "Môj životný cieľ je byť taký dobrý človek, akým ma môj pes už teraz považuje.",
  "10-05": "Je tvojím priateľom, partnerom, obrancom, tvojím psom. Ty si jeho životom, jeho láskou, jeho vodcom. Bude ti verný a oddaný až do posledného úderu svojho srdca. Dlhuješ mu, aby si bol hoden takej oddanosti.",
  "10-06": "Pes pri hre má myseľ múdreho majstra bojových umení — myseľ schopnú dokonalého sústredenia.",
  "10-07": "Nikdy neveruj psovi, že bude strážiť tvoje jedlo.",
  "10-08": "Psy a mačky inštinktívne vedia presný okamih, keď sa ich majitelia zobudia. A potom ich zobudia o 10 minút skôr.",
  "10-09": "Práca môže počkať ďalších 30 minút. Existujú dôležitejšie veci. Napríklad hádzanie palíc.",
  "10-10": "Ty nevlastníš psa — pes vlastní teba.",
  "10-11": "Ktokoľvek povedal, že diamanty sú najlepším priateľom ženy, nikdy nemal psa.",
  "10-12": "Niektorí ľudia rozprávajú so zvieratami. Len málokto však počúva. To je ten problém.",
  "10-13": "Šťastie sa nedá kúpiť, ale dá sa zachrániť.",
  "10-14": "Aký krásny svet by to bol, keby mali ľudia srdcia ako psy.",
  "10-15": "Keby sa najláskavejším dušiam odmeňovalo najdlhším životom, psy by nás všetkých prežili.",
  "10-16": "Nie každý vie milovať psa, ale každý pes vie milovať človeka.",
  "10-17": "Zvyčajne spoznáš, že je človek dobrý, keď má psa, ktorý ho miluje.",
  "10-18": "Zachrániť jedného psa nezmení svet, ale určite pre toho jedného psa sa svet zmení navždy.",
  "10-19": "Nikdy nehryź, keď postačí vrčanie.",
  "10-20": "Čistotu ľudského srdca možno rýchlo odmerať podľa toho, ako sa správa k zvieratám.",
  "10-21": "Niektorí anjeli si volia srsť namiesto krídel.",
  "10-22": "Miloval som ťa celý tvoj život a budem ti chýbať po zvyšok môjho.",
  "10-23": "Moja myseľ sa s tebou stále rozpráva a moje srdce ťa stále hľadá, ale moja duša vie, že si v pokoji.",
  "10-24": "Všetko, čo viem, som sa naučila od psov.",
  "10-25": "Keď myslíme na tých spoločníkov, ktorí kráčali po našom boku cestou života, nehovorme so smútkom, že nás opustili, ale radšej s tichou vďakou, že boli raz s nami.",
  "10-26": "Tvoje krídla boli pripravené, ale moje srdce nie.",
  "10-27": "Láska je slovo na štyri labky.",
  "10-28": "Cesta k môjmu srdcu je vydláždená odtlačkami labiek.",
  "10-29": "Nie sú zlé dni, keď sa vraciaš domov k psej láske.",
  "10-30": "Bez ohľadu na to, koľko máš peňazí a vecí, pes ťa robí bohatým.",
  "10-31": "Každý potrebuje psa, ktorý ho zbožňuje, a mačku, ktorá ho vracia späť do reality.",
  "11-01": "Keby ťa láska samotná mohla udržať tu s nami, žil by si naveky.",
  "11-02": "Keď sa niekto, koho milujeme, stane spomienkou, tá spomienka sa stáva pokladom.",
  "11-03": "Svet by bol krajším miestom, keby každý dokázal milovať tak bezpodmienečne ako pes.",
  "11-04": "Pre psa je celý svet vôňou.",
  "11-05": "Každý chlapec by mal mať dve veci: psa a matku, ktorá mu ho dovolí mať.",
  "11-06": "Pes je jediné zviera, ktoré videlo svojho boha.",
  "11-07": "Kúp jedného psa, dostaneš jednu blchu.",
  "11-08": "Každý strom má kôru. Každý pes štekáš. Teda všetky psy sú stromy.",
  "11-09": "Mačacie motto: nech sa stane čokoľvek, vždy sa postaraj o to, aby to vyzeral urobiť pes.",
  "11-10": "Najmenšie labky zanechávajú najväčšiu stopu v našich srdciach.",
  "11-11": "Keby Boh vyslyšal psie modlitby, pršalo by z neba kosti.",
  "11-12": "Pes sa k tebe zachová lepšie ako ktokoľvek, koho stretnete na večierku.",
  "11-13": "V psích rokoch som už mŕtvy.",
  "11-14": "Psy prídu, keď ich zavoláš. Mačky si správu vypočujú a ozvú sa neskôr.",
  "11-15": "Všimli ste si niekedy, že keď sfúknete psovi do tváre, nahnevá sa na vás? Ale keď ho veziete autom, vyčnieva hlavou z okna.",
  "11-16": "Naše psy budú milovať a obdivovať aj toho najhoršieho z nás a kŕmiť naše kolosálne márnomyseľnosti svojou nekritickou oddanosťou.",
  "11-17": "Najväčšia radosť pri psovi je, že si pri ňom môžeš robiť zo seba blázna — a on ťa nielen neokará, ale sa spolu s tebou zblázni tiež.",
  "11-18": "Čím viac vídavam zástupcov ľudu, tým viac obdivujem svojich psov.",
  "11-19": "Stalo sa vám niekedy, že ste vstúpili do miestnosti a zabudli ste prečo? Myslím, že presne takto trávia psy celý život.",
  "11-20": "Nikto nedocení jedinečný génius vášho rozhovoru tak ako pes.",
  "11-21": "Pes je často tou správnou odpoveďou — keď si osamelý a chceš spoločnosť, alebo keď si unavený zo spoločnosti a chceš samotu.",
  "11-22": "Každý by mal mať psa z útulku. Je to dobré pre dušu.",
  "11-23": "Pes bol stvorený špeciálne pre deti. Je to boh hravosti.",
  "11-24": "Nikto nám nerozumie tak dokonale ako psy a kone.",
  "11-25": "Keby psy vedeli hovoriť, možno by sme s nimi vychádzali rovnako ťažko ako s ľuďmi.",
  "11-26": "Keď ich ráno opúšťate, strčia nos do škáry dverí a stoja tam ako na portréte, kým o osem hodín neskôr neotočíte kľúčom.",
  "11-27": "Je mu tak neskutočne dobre, že žije, až musí vrtieť svojím radostným chvostíkom.",
  "11-28": "Najväčšia láska: materská, potom psova, potom láska milovanej osoby.",
  "11-29": "Dúfam, že raz budem taký človek, akým si myslí môj pes, že som.",
  "11-30": "Psy majú dar nachádzať ľudí, ktorí ich potrebujú, a vypĺňať prázdnotu, o ktorej sme ani nevedeli, že ju máme.",
  "12-01": "Čierny pes dostane jedlo; biely pes dostane vinu.",
  "12-02": "Psia búda nie je miesto na ukladanie klobásy.",
  "12-03": "Pes je vo vlastnom dome levom.",
  "12-04": "Psy nie sú celý náš život, ale robia náš život celistvým.",
  "12-05": "Neukazuj palicu psovi, ktorého už bili.",
  "12-06": "Dom bez psa, mačky alebo dieťaťa je bez radosti.",
  "12-07": "Keď ťa vlk pozve dnu, vezmi so sebou psa.",
  "12-08": "Pes bez chvosta nedokáže vyjadriť svoju radosť.",
  "12-09": "Psy, čo sa bijú medzi sebou, sa spoja proti vlkovi.",
  "12-10": "Pes je jediná bytosť na svete, ktorá ťa miluje viac ako seba samého.",
  "12-11": "Fox-teriéri sa rodia so štvornásobným množstvom prvotného hriechu oproti iným psom.",
  "12-12": "Starý pes, ešte viac ako starý manžel, vždy chce to isté, čo chceš ty.",
  "12-13": "Čas, ktorý potrebuje pes na „vykonanie svojej potreby\", je priamo úmerný vonkajšej teplote a vhodnosti odevu majiteľa.",
  "12-14": "Premýšľal si niekedy, kde by si skončil, keby si vzal psa na prechádzku a ani raz nepotiahol za vodítko?",
  "12-15": "Psy majú dar nájsť ľudí, ktorí ich potrebujú — vyplniť prázdnotu, o ktorej sme ani nevedeli, že ju máme.",
  "12-16": "Za peniaze si kúpiš skvelého psa, ale len láska ho prinúti krútiť chvostom.",
  "12-17": "Svet by bol krajším miestom, keby každý dokázal milovať tak bezpodmienečne ako pes.",
  "12-18": "Keď ti štyridsaťkilogramový tvor olíže slzy a potom sa ti pokúsi sadnúť na kolená, je ťažké byť smutný.",
  "12-19": "Pes dokáže chvostom za pár sekúnd vyjadriť viac ako jeho majiteľ jazykom za celé hodiny.",
  "12-20": "Šťastie je teplé šteňa.",
  "12-21": "Ktokoľvek tvrdil, že šťastie sa nedá kúpiť, zabudol na malé šteňatá.",
  "12-22": "Puto s pravým psom je také trvalé, aké môžu byť putá tejto zeme.",
  "12-23": "Psy sú zázraky na labkách.",
  "12-24": "Pes je jediná bytosť na svete, ktorá ťa miluje viac ako seba samého.",
  "12-25": "Úbohý pes — za života najvernejší priateľ, prvý, kto ťa víta, prvý, kto ťa bráni.",
  "12-26": "Dom nie je domovom, kým v ňom nie je pes.",
  "12-27": "Psy zanechávajú odtlačky labiek na našich srdciach.",
  "12-28": "Myslím, že psy sú najúžasnejšie tvory — dávajú bezpodmienečnú lásku. Pre mňa sú vzorom toho, ako žiť.",
  "12-29": "Správne vycvičený môže byť aj človek najlepším priateľom psa.",
  "12-30": "Starí psi sú ako staré topánky — pohodlní. Možno trochu stratili tvar a sú ošúchaní po okrajoch, ale sadnú dobre.",
  "12-31": "Ak zdvihneš hladujúceho psa a urobíš z neho prosperujúceho, nebudeš sa ho báť. To je hlavný rozdiel medzi psom a človekom.",
};
